<?php if($management&&$page==='usuarios'): ?><p><a class="button" href="?page=usuarios&staff=1">Ver docentes y equipo directivo →</a></p><?php endif; ?>
<?php if(!$selectedGrade): ?><p>Primero elige un grado. Después selecciona el salón para trabajar con sus cursos y estudiantes.</p><div class="courses"><?php foreach([1,2,3,4,5] as $grade):$rooms=array_filter($groups,fn($g)=>(int)$g['grade_level']===$grade);if(!$rooms)continue; ?><a class="activity" href="?page=<?= escape($page) ?>&grade=<?= $grade ?>"><span class="eyebrow">SECUNDARIA</span><h2><?= $grade ?>° grado →</h2><p><?= count($rooms) ?> salones disponibles</p></a><?php endforeach; ?></div>
<?php else: ?><p><a href="?page=<?= escape($page) ?>">← Todos los grados</a></p><h2><?= $selectedGrade ?>° grado · Elige un salón</h2><div class="courses"><?php foreach($groups as $g):if((int)$g['grade_level']!==$selectedGrade)continue;$count=(int)query("SELECT COUNT(*) FROM eval_users WHERE group_id=? AND role='estudiante' AND active=1",[$g['id']])->fetchColumn();$courseCount=(int)query('SELECT COUNT(*) FROM eval_courses WHERE group_id=?'.($teacher?' AND teacher_id=?':''),$teacher?[$g['id'],$user['id']]:[$g['id']])->fetchColumn(); ?><a class="activity" href="?page=<?= escape($page) ?>&grade=<?= $selectedGrade ?>&group=<?= (int)$g['id'] ?>"><span class="eyebrow">SALÓN</span><h2><?= escape($g['name']) ?> →</h2><p><?= $count ?> estudiantes · <?= $courseCount ?> cursos<?= $teacher?' asignados':'' ?></p></a><?php endforeach; ?></div><?php endif; ?>
